import Ajv, {type ErrorObject, type Options, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

function formatInstancePath(instancePath: string): string {
  return instancePath ? instancePath.slice(1).replaceAll('/', '.') : 'input';
}

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({strict: false, validateFormats: false} as Options);
  private readonly schemaValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileValidator(name: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      return this.validator.compile(schema);
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${name}: ${detail}`, {cause: error});
    }
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) return tool.validator;
    const schema = definition.inputSchema;
    const cached = this.schemaValidators.get(schema);
    if (cached) return cached;
    const validator = this.compileValidator(definition.name, schema);
    this.schemaValidators.set(schema, validator);
    return validator;
  }

  private rejection(error: ErrorObject): ToolResponse {
    if (error.keyword === 'required') {
      const missingProperty = 'missingProperty' in error.params ? error.params.missingProperty : 'unknown';
      return {result: `Input property ${String(missingProperty)} is required`};
    }
    const path = formatInstancePath(error.instancePath);
    const expected =
      'type' in error.params && typeof error.params.type === 'string' ? ` to be ${error.params.type}` : '';
    return {result: `${path} is invalid${expected}`};
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator =
      typeof definition === 'function' ? undefined : this.compileValidator(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.validatorFor(tool, definition);
    if (!validate(input))
      return this.rejection(validate.errors?.[0] ?? ({keyword: 'validation', params: {}} as ErrorObject));
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('returns a required-property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'required_location',
        description: 'Requires a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('required_location', {});

    expect({result: response.result, executorCalls}).toEqual({
      result: expect.stringMatching(/location.*required/i),
      executorCalls: 0,
    });
  });

  it('reports the failing property path for a wrong-typed input', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_location',
        description: 'Looks up a location',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {city: {type: 'string'}},
            },
          },
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('lookup_location', {profile: {city: 123456789}});

    expect(response.result).toBe('profile.city is invalid to be string');
  });

  it('reuses a static schema validator across execute calls', async () => {
    const inputSchema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const registry = new ToolRegistry();
    const inputs: Array<Record<string, unknown>> = [];
    registry.register({name: 'get_weather', description: 'Get weather', inputSchema}, async input => {
      inputs.push(input);
      return 'sunny';
    });

    inputSchema.required = ['city'];
    const responses = await Promise.all(
      Array.from({length: 10}, () => registry.execute('get_weather', {location: 'Paris'}))
    );

    expect({
      responses: responses.map(response => response.result),
      inputs,
    }).toEqual({
      responses: Array(10).fill('sunny'),
      inputs: Array(10).fill({location: 'Paris'}),
    });
  });

  it('validates each function-valued schema against the definition current at that call', async () => {
    const locationSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const citySchema = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    let definitionCalls = 0;
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Uses a changing schema',
        inputSchema: definitionCalls++ < 2 ? locationSchema : citySchema,
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const firstResponse = await registry.execute('dynamic_weather', {});
    const secondResponse = await registry.execute('dynamic_weather', {city: 42});

    expect({
      firstResult: firstResponse.result,
      secondResult: secondResponse.result,
      executorCalls,
    }).toEqual({
      firstResult: expect.stringMatching(/location.*required/i),
      secondResult: 'city is invalid to be string',
      executorCalls: 0,
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: returns a required-property rejection without invoking the executor](../../src/orchestration/tools/registry.test.ts#L4), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: reports the failing property path for a wrong-typed input](../../src/orchestration/tools/registry.test.ts#L27), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: reuses a static schema validator across execute calls](../../src/orchestration/tools/registry.test.ts#L27)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each function-valued schema against the definition current at that call](../../src/orchestration/tools/registry.test.ts#L54)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
